@using sv_0df09a8d69cf45a2ae2d44d422959156

<div class="card mb-2">
    <div class="card-body p-2">
        <h6 class="card-title mb-1">@Task.Title</h6>
        <p class="card-text mb-1 text-muted small">@Task.Assignee</p>
        <span class="badge @PriorityClass me-1">@Task.Priority</span>
        <small class="text-muted">@Task.DueDate.ToString("MMM dd")</small>
        <div class="mt-2 d-flex gap-1">
            @if (CanMoveLeft)
            {
                <button class="btn btn-outline-secondary btn-sm" @onclick="OnMoveLeft" disabled="@IsMoving">
                    &larr; Move Left
                </button>
            }
            @if (CanMoveRight)
            {
                <button class="btn btn-outline-secondary btn-sm" @onclick="OnMoveRight" disabled="@IsMoving">
                    Move Right &rarr;
                </button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback MoveLeftClicked { get; set; }
    [Parameter] public EventCallback MoveRightClicked { get; set; }

    private bool IsMoving;

    private string PriorityClass => Task.Priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async System.Threading.Tasks.Task OnMoveLeft()
    {
        IsMoving = true;
        await MoveLeftClicked.InvokeAsync();
        IsMoving = false;
    }

    private async System.Threading.Tasks.Task OnMoveRight()
    {
        IsMoving = true;
        await MoveRightClicked.InvokeAsync();
        IsMoving = false;
    }
}

@using sv_0df09a8d69cf45a2ae2d44d422959156

<div class="card border-primary mb-2">
    <div class="card-body p-2">
        <div class="mb-2">
            <input type="text" class="form-control form-control-sm" placeholder="Title"
                   @bind="Title" @bind:event="oninput" />
        </div>
        <div class="mb-2">
            <input type="text" class="form-control form-control-sm" placeholder="Assignee"
                   @bind="Assignee" @bind:event="oninput" />
        </div>
        <div class="mb-2">
            <select class="form-select form-select-sm" @bind="Priority">
                <option value="High">High</option>
                <option value="Medium">Medium</option>
                <option value="Low">Low</option>
            </select>
        </div>
        <div class="mb-2">
            <input type="date" class="form-control form-control-sm" @bind="DueDate" />
        </div>
        @if (!string.IsNullOrEmpty(Error))
        {
            <div class="text-danger small mb-2">@Error</div>
        }
        <div class="d-flex gap-1">
            <button class="btn btn-primary btn-sm" @onclick="HandleSave" disabled="@IsSaving">
                @(IsSaving ? "Saving..." : "Save")
            </button>
            <button class="btn btn-secondary btn-sm" @onclick="HandleCancel" disabled="@IsSaving">Cancel</button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public EventCallback<TaskItem> TaskCreated { get; set; }
    [Parameter] public EventCallback Cancelled { get; set; }

    private string Title = "";
    private string Assignee = "";
    private string Priority = "Medium";
    private DateTime DueDate = DateTime.Today.AddDays(7);
    private string? Error;
    private bool IsSaving;

    [Inject] private ITaskService TaskService { get; set; } = default!;

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(Title))
        {
            Error = "Title is required.";
            return;
        }

        Error = null;
        IsSaving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(Title.Trim(), Assignee.Trim(), Priority, DueDate);
            // The service creates with a default status; if the column status differs, update it
            if (created.Status != Status)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, Status);
                created = created with { Status = Status };
            }
            await TaskCreated.InvokeAsync(created);
        }
        catch (Exception ex)
        {
            Error = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            IsSaving = false;
        }
    }

    private async Task HandleCancel()
    {
        await Cancelled.InvokeAsync();
    }
}

@using sv_0df09a8d69cf45a2ae2d44d422959156

<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@ColumnName</h5>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body p-2" style="min-height: 200px; overflow-y: auto;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          CanMoveLeft="CanMoveLeft"
                          CanMoveRight="CanMoveRight"
                          MoveLeftClicked="() => OnMoveLeft(task)"
                          MoveRightClicked="() => OnMoveRight(task)" />
            }

            @if (ShowForm)
            {
                <AddTaskForm Status="@Status"
                             TaskCreated="HandleTaskCreated"
                             Cancelled="() => ShowForm = false" />
            }
        </div>
        <div class="card-footer">
            <button class="btn btn-outline-primary btn-sm w-100" @onclick="() => ShowForm = true"
                    disabled="@ShowForm">
                + Add Task
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> MoveLeftRequested { get; set; }
    [Parameter] public EventCallback<TaskItem> MoveRightRequested { get; set; }
    [Parameter] public EventCallback<TaskItem> TaskAdded { get; set; }

    private bool ShowForm;

    private async Task OnMoveLeft(TaskItem task) => await MoveLeftRequested.InvokeAsync(task);
    private async Task OnMoveRight(TaskItem task) => await MoveRightRequested.InvokeAsync(task);

    private async Task HandleTaskCreated(TaskItem task)
    {
        ShowForm = false;
        await TaskAdded.InvokeAsync(task);
    }
}

@page "/board"
@rendermode InteractiveServer
@using sv_0df09a8d69cf45a2ae2d44d422959156

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Tasks="tasks" />
    <BoardSearchBar SearchText="@searchText" SearchTextChanged="HandleSearchChanged" />

    <div class="row g-3">
        <KanbanColumn ColumnName="To Do" Status="To Do"
                      Tasks="GetFilteredTasks("To Do")"
                      CanMoveLeft="false" CanMoveRight="true"
                      MoveRightRequested="t => MoveTask(t, "In Progress")"
                      TaskAdded="HandleTaskAdded" />

        <KanbanColumn ColumnName="In Progress" Status="In Progress"
                      Tasks="GetFilteredTasks("In Progress")"
                      CanMoveLeft="true" CanMoveRight="true"
                      MoveLeftRequested="t => MoveTask(t, "To Do")"
                      MoveRightRequested="t => MoveTask(t, "Done")"
                      TaskAdded="HandleTaskAdded" />

        <KanbanColumn ColumnName="Done" Status="Done"
                      Tasks="GetFilteredTasks("Done")"
                      CanMoveLeft="true" CanMoveRight="false"
                      MoveLeftRequested="t => MoveTask(t, "In Progress")"
                      TaskAdded="HandleTaskAdded" />
    </div>
}

@code {
    [Inject] private ITaskService TaskService { get; set; } = default!;

    private List<TaskItem> tasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t =>
                t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = tasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                tasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void HandleTaskAdded(TaskItem task)
    {
        tasks.Add(task);
    }
}

