+    [Parameter, EditorRequired] public string Status { get; set; } = default!;
+    [Parameter] public EventCallback<TaskItem> TaskCreated { get; set; }
+    [Parameter] public EventCallback Cancelled { get; set; }
+
+    private string Title = "";
+    private string Assignee = "";
+    private string Priority = "Medium";
+    private DateTime DueDate = DateTime.Today.AddDays(7);
+    private string? Error;
+    private bool IsSaving;
+
+    [Inject] private ITaskService TaskService { get; set; } = default!;
+
+    private async Task HandleSave()
+    {
+        if (string.IsNullOrWhiteSpace(Title))
+        {
+            Error = "Title is required.";
+            return;
+        }
+
+        Error = null;
+        IsSaving = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(Title.Trim(), Assignee.Trim(), Priority, DueDate);
+            // The service creates with a default status; if the column status differs, update it
+            if (created.Status != Status)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, Status);
+                created = created with { Status = Status };
+            }
+            await TaskCreated.InvokeAsync(created);
+        }
+        catch (Exception ex)
+        {
+            Error = $"Failed to create task: {ex.Message}";
+        }
+        finally
+        {
+            IsSaving = false;
+        }
+    }
+
+    private async Task HandleCancel()
+    {
+        await Cancelled.InvokeAsync();
+    }
+}
+

