@using sv_0df09a8d69cf45a2ae2d44d422959156

<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@ColumnName</h5>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body p-2" style="min-height: 200px; overflow-y: auto;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          CanMoveLeft="CanMoveLeft"
                          CanMoveRight="CanMoveRight"
                          MoveLeftClicked="() => OnMoveLeft(task)"
                          MoveRightClicked="() => OnMoveRight(task)" />
            }

            @if (ShowForm)
            {
                <AddTaskForm Status="@Status"
                             TaskCreated="HandleTaskCreated"
                             Cancelled="() => ShowForm = false" />
            }
        </div>
        <div class="card-footer">
            <button class="btn btn-outline-primary btn-sm w-100" @onclick="() => ShowForm = true"
                    disabled="@ShowForm">
                + Add Task
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> MoveLeftRequested { get; set; }
    [Parameter] public EventCallback<TaskItem> MoveRightRequested { get; set; }
    [Parameter] public EventCallback<TaskItem> TaskAdded { get; set; }

    private bool ShowForm;

    private async Task OnMoveLeft(TaskItem task) => await MoveLeftRequested.InvokeAsync(task);
    private async Task OnMoveRight(TaskItem task) => await MoveRightRequested.InvokeAsync(task);

    private async Task HandleTaskCreated(TaskItem task)
    {
        ShowForm = false;
        await TaskAdded.InvokeAsync(task);
    }
}

